sys_variable_value.value:
(function execute(inputs, outputs) {
   var fieldMapping = {
       "v_superavit_tribunal_de_contas": "superavit_tribunal_de_contas",
       "v_superavit_judiciario": "superavit_judiciario",
       "v_superavit_executivo": "superavit_executivo",
       "v_superavit_ministerio_publico": "superavit_ministerio_publico",
       "v_superavit_legislativo": "superavit_legislativo",
       "v_superavit_total": "superavit_total",
       "v_superavit_defensoria": "superavit_defensoria",
       "v_ano": "ano"
   };


   var grMultiRow = new GlideRecord('sc_multi_row_question_answer');
   grMultiRow.addEncodedQuery('row_index=' + inputs.row_index + '^parent_id=' + inputs.parent_id);
   grMultiRow.query();

   while (grMultiRow.next()) {
       var questionName = grMultiRow.item_option_new.name;
       var value = grMultiRow.getValue('value');

       if (fieldMapping[questionName]) {
           fieldMapping[questionName] = value;
       }
   }

outputs.superavit_tribunal_de_contas = fieldMapping['v_superavit_tribunal_de_contas'];
outputs.superavit_judiciario = fieldMapping['v_superavit_judiciario'];
outputs.superavit_executivo = fieldMapping['v_superavit_executivo'];
outputs.superavit_ministerio_publico = fieldMapping['v_superavit_ministerio_publico'];
outputs.superavit_legislativo = fieldMapping['v_superavit_legislativo'];
outputs.superavit_total = fieldMapping['v_superavit_total'];
outputs.superavit_defensoria = fieldMapping['v_superavit_defensoria'];
outputs.ano = fieldMapping['v_ano'];

})(inputs, outputs);

